INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_026_M6_S5', 'sequence models', '5', 'sequence models: Models designed to learn dependencies among ordered observations such as words, signals, or time-series values. In Neural Networks and Deep Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of sequence models within Machine Learning, particularly where the Neural Networks and Deep Learning module establishes its technical context.', 'SSD_COURSE_026_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M6_S6', 'optimization', '6', 'optimization: Selection of decision variables or operating conditions to maximize or minimize an objective subject to specified constraints; the objective and constraints depend on the application domain. In Neural Networks and Deep Learning, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_026_M6_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S1', 'cross-validation', '1', 'cross-validation: Cross-validation repeatedly partitions available data into training and validation subsets to estimate model performance and support model selection. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of cross-validation within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S2', 'calibration', '2', 'calibration: Adjusting predicted probabilities so that they correspond appropriately to observed outcome frequencies; in ML this concerns probabilistic prediction calibration, not instrument adjustment. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of calibration within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S3', 'imbalanced data', '3', 'imbalanced data refers to a dataset in which some classes or outcomes occur much less often than others. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of imbalanced data within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S4', 'hyperparameter selection', '4', 'hyperparameter selection: Choosing model settings that are not learned directly from the training data, typically using validation procedures or cross-validation. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of hyperparameter selection within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S5', 'model monitoring', '5', 'model monitoring: Tracking a deployed model''s inputs, outputs, performance, and operating conditions to detect degradation or drift. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of model monitoring within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M7_S6', 'reproducibility', '6', 'reproducibility refers to the ability to obtain consistent results when the same analysis, data, methods, and documented computational steps are repeated. In Model Evaluation and Deployment, the focus is on the analysis, design, implementation, interpretation, or evaluation of reproducibility within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_026_M7_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M1_S1', 'system models', '1', 'system models: Abstract assumptions about processes, communication, timing, failures, and resources in a distributed system. In Distributed System Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of system models within Distributed Systems, particularly where the Distributed System Models module establishes its technical context.', 'SSD_COURSE_027_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M1_S2', 'communication models', '2', 'communication models: Assumptions about how distributed processes exchange messages, including timing, ordering, and delivery guarantees. In Distributed System Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of communication models within Distributed Systems, particularly where the Distributed System Models module establishes its technical context.', 'SSD_COURSE_027_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M1_S3', 'time and ordering', '3', 'time and ordering: Methods for reasoning about event order when distributed processes do not share a perfectly synchronised clock. In Distributed System Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of time and ordering within Distributed Systems, particularly where the Distributed System Models module establishes its technical context.', 'SSD_COURSE_027_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M1_S4', 'failure models', '4', 'failure models: Formal assumptions about how components or processes may fail in a distributed system, such as crash, omission, timing, or Byzantine failures. In Distributed System Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of failure models within Distributed Systems, particularly where the Distributed System Models module establishes its technical context.', 'SSD_COURSE_027_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M1_S5', 'scalability', '5', 'scalability refers to the ability of a distributed system to maintain acceptable performance as workload, data, or nodes increase. In Distributed System Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of scalability within Distributed Systems, particularly where the Distributed System Models module establishes its technical context.', 'SSD_COURSE_027_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S1', 'Remote Procedure Call (RPC)', '1', 'Remote Procedure Call (RPC) refers to a communication mechanism that lets a program invoke an operation on a remote process using a call-like interface. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of RPC within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S2', 'messaging', '2', 'messaging: Exchange of discrete messages between distributed components to coordinate work or transfer data. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of messaging within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S3', 'multicast', '3', 'multicast: Sending one message to multiple intended recipients in a distributed network. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of multicast within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S4', 'logical clocks', '4', 'logical clocks: Logical mechanisms for ordering distributed events without relying on synchronised physical clocks. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of logical clocks within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S5', 'leader election', '5', 'leader election refers to a protocol for selecting one distributed process to coordinate activities or make designated decisions. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of leader election within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M2_S6', 'distributed coordination', '6', 'distributed coordination: Protocols that allow independent processes to reach compatible decisions or organise shared work. In Communication and Coordination, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed coordination within Distributed Systems, particularly where the Communication and Coordination module establishes its technical context.', 'SSD_COURSE_027_M2_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M3_S1', 'primary-backup replication', '1', 'primary-backup replication: Replication in which a primary processes updates and backups maintain copies for continuity after failure. In Replication and Consistency, the focus is on the analysis, design, implementation, interpretation, or evaluation of primary-backup replication within Distributed Systems, particularly where the Replication and Consistency module establishes its technical context.', 'SSD_COURSE_027_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M3_S2', 'quorum systems', '2', 'quorum systems: Sets of replicas whose agreement or participation is required for an operation to proceed safely. In Replication and Consistency, the focus is on the analysis, design, implementation, interpretation, or evaluation of quorum systems within Distributed Systems, particularly where the Replication and Consistency module establishes its technical context.', 'SSD_COURSE_027_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M3_S3', 'consistency models', '3', 'consistency models: Rules defining what values and operation orders clients may observe from replicated data. In Replication and Consistency, the focus is on the analysis, design, implementation, interpretation, or evaluation of consistency models within Distributed Systems, particularly where the Replication and Consistency module establishes its technical context.', 'SSD_COURSE_027_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M3_S4', 'consensus', '4', 'consensus refers to a distributed protocol that makes non-faulty processes agree on one value despite specified failures. In Replication and Consistency, the focus is on the analysis, design, implementation, interpretation, or evaluation of consensus within Distributed Systems, particularly where the Replication and Consistency module establishes its technical context.', 'SSD_COURSE_027_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M3_S5', 'conflict resolution', '5', 'conflict resolution: Rules for reconciling concurrent or incompatible updates to shared distributed state. In Replication and Consistency, the focus is on the analysis, design, implementation, interpretation, or evaluation of conflict resolution within Distributed Systems, particularly where the Replication and Consistency module establishes its technical context.', 'SSD_COURSE_027_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M4_S1', 'atomic commit', '1', 'atomic commit refers to a protocol ensuring that a distributed transaction is either committed by all required participants or aborted. In Distributed Transactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of atomic commit within Distributed Systems, particularly where the Distributed Transactions module establishes its technical context.', 'SSD_COURSE_027_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M4_S2', 'two-phase commit', '2', 'two-phase commit refers to a distributed commit protocol using prepare and commit phases to coordinate transaction outcome. In Distributed Transactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of two-phase commit within Distributed Systems, particularly where the Distributed Transactions module establishes its technical context.', 'SSD_COURSE_027_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M4_S3', 'distributed concurrency control', '3', 'distributed concurrency control: Coordination mechanisms that keep concurrent operations on distributed data consistent while allowing appropriate parallel execution. In Distributed Transactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed concurrency control within Distributed Systems, particularly where the Distributed Transactions module establishes its technical context.', 'SSD_COURSE_027_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M4_S4', 'serializability', '4', 'serializability refers to the property that concurrent transaction execution has an effect equivalent to some serial order. In Distributed Transactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of serializability within Distributed Systems, particularly where the Distributed Transactions module establishes its technical context.', 'SSD_COURSE_027_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M4_S5', 'recovery', '5', 'recovery: Restoring a distributed system or transaction to a correct state after a failure, using mechanisms such as logging, checkpoints, rollback, or replay. In Distributed Transactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of recovery within Distributed Systems, particularly where the Distributed Transactions module establishes its technical context.', 'SSD_COURSE_027_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M5_S1', 'partitioning', '1', 'partitioning: Dividing data or workload across nodes so that storage and processing can be distributed. In Distributed Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of partitioning within Distributed Systems, particularly where the Distributed Storage module establishes its technical context.', 'SSD_COURSE_027_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M5_S2', 'distributed hash tables', '2', 'distributed hash tables: Distributed data structures that map keys to responsible nodes for scalable lookup. In Distributed Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed hash tables within Distributed Systems, particularly where the Distributed Storage module establishes its technical context.', 'SSD_COURSE_027_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M5_S3', 'distributed file systems', '3', 'distributed file systems: File systems that store and manage files across multiple networked machines. In Distributed Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed file systems within Distributed Systems, particularly where the Distributed Storage module establishes its technical context.', 'SSD_COURSE_027_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M5_S4', 'object storage', '4', 'object storage refers to a storage architecture in which data are managed as objects containing payload data, metadata, and a unique identifier within a logical namespace. In Distributed Storage, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_027_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M5_S5', 'metadata management', '5', 'metadata management: Maintaining information about distributed files, objects, nodes, locations, and system state. In Distributed Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of metadata management within Distributed Systems, particularly where the Distributed Storage module establishes its technical context.', 'SSD_COURSE_027_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M6_S1', 'failure detection', '1', 'failure detection: Identifying components that are suspected to have failed, typically from timeouts, heartbeats, acknowledgements, or other observations. In Fault Tolerance and Recovery, the focus is on the analysis, design, implementation, interpretation, or evaluation of failure detection within Distributed Systems, particularly where the Fault Tolerance and Recovery module establishes its technical context.', 'SSD_COURSE_027_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M6_S2', 'redundancy', '2', 'redundancy: Provision of duplicate or alternative components, paths, or resources so that loss or failure of one element does not necessarily cause loss of required service. In Fault Tolerance and Recovery, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_027_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M6_S3', 'checkpointing', '3', 'checkpointing: Saving recoverable system state so computation can resume after a failure. In Fault Tolerance and Recovery, the focus is on the analysis, design, implementation, interpretation, or evaluation of checkpointing within Distributed Systems, particularly where the Fault Tolerance and Recovery module establishes its technical context.', 'SSD_COURSE_027_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M6_S4', 'recovery protocols', '4', 'recovery protocols: Protocols that coordinate restoration of consistent system state after failures, including rollback, replay, checkpointing, or state reconstruction. In Fault Tolerance and Recovery, the focus is on the analysis, design, implementation, interpretation, or evaluation of recovery protocols within Distributed Systems, particularly where the Fault Tolerance and Recovery module establishes its technical context.', 'SSD_COURSE_027_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M6_S5', 'Byzantine failures', '5', 'Byzantine failures: Failures in which a distributed component may behave arbitrarily or inconsistently, including sending conflicting or misleading information. In Fault Tolerance and Recovery, the focus is on the analysis, design, implementation, interpretation, or evaluation of Byzantine failures within Distributed Systems, particularly where the Fault Tolerance and Recovery module establishes its technical context.', 'SSD_COURSE_027_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M7_S1', 'availability', '1', 'availability refers to the ability of a distributed service to remain accessible and responsive when components fail. In Distributed System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of availability within Distributed Systems, particularly where the Distributed System Design module establishes its technical context.', 'SSD_COURSE_027_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M7_S2', 'partition tolerance', '2', 'partition tolerance refers to the ability to continue operating when network partitions prevent some nodes from communicating. In Distributed System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of partition tolerance within Distributed Systems, particularly where the Distributed System Design module establishes its technical context.', 'SSD_COURSE_027_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M7_S3', 'load balancing', '3', 'load balancing: Distribution of computational, network, or service workload across available resources to improve utilization, throughput, latency, or availability. In Distributed System Design, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_027_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M7_S4', 'observability', '4', 'observability refers to the ability to infer distributed-system behaviour from logs, metrics, traces, and other telemetry. In Distributed System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of observability within Distributed Systems, particularly where the Distributed System Design module establishes its technical context.', 'SSD_COURSE_027_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_027_M7_S5', 'performance trade-offs', '5', 'performance trade-offs: Design choices that balance latency, throughput, consistency, availability, resource use, and other system objectives. In Distributed System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of performance trade-offs within Distributed Systems, particularly where the Distributed System Design module establishes its technical context.', 'SSD_COURSE_027_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M1_S1', 'IaaS', '1', 'IaaS: Cloud delivery of virtualised or physical computing, storage, and networking resources that users configure and manage. In Cloud Computing Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of IaaS within Cloud Computing and Virtualization, particularly where the Cloud Computing Models module establishes its technical context.', 'SSD_COURSE_028_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M1_S2', 'PaaS', '2', 'PaaS: Cloud delivery of a managed application platform on which users deploy code without managing the underlying infrastructure. In Cloud Computing Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of PaaS within Cloud Computing and Virtualization, particularly where the Cloud Computing Models module establishes its technical context.', 'SSD_COURSE_028_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M1_S3', 'SaaS', '3', 'SaaS: Cloud delivery of complete software applications managed by the provider and accessed by users as a service. In Cloud Computing Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of SaaS within Cloud Computing and Virtualization, particularly where the Cloud Computing Models module establishes its technical context.', 'SSD_COURSE_028_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M1_S4', 'public/private/hybrid cloud', '4', 'public/private/hybrid cloud: Cloud deployment models that differ in ownership, isolation, and combination of provider and organisational infrastructure. In Cloud Computing Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of public/private/hybrid cloud within Cloud Computing and Virtualization, particularly where the Cloud Computing Models module establishes its technical context.', 'SSD_COURSE_028_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M1_S5', 'shared responsibility', '5', 'shared responsibility refers to a security model that divides operational and security responsibilities between the cloud provider and customer. In Cloud Computing Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of shared responsibility within Cloud Computing and Virtualization, particularly where the Cloud Computing Models module establishes its technical context.', 'SSD_COURSE_028_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M2_S1', 'hypervisors', '1', 'hypervisors: Software or firmware layers that create and manage virtual machines by controlling access to physical computing resources. In Virtualization Technologies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_028_M2_S1', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;